// PostgREST devolve o jsonb da função escalar direto no corpo.
const raw = $input.first().json;
const p = Array.isArray(raw) ? raw[0] : raw;

if (!p || p.empresa === undefined) {
  throw new Error('Payload inesperado da RPC: ' + JSON.stringify(raw).slice(0, 300));
}

const brl = (v) => Number(v || 0).toLocaleString('pt-BR', {
  style: 'currency', currency: 'BRL',
});

// Meses à mão em vez de toLocaleDateString: em pt-BR o formato 'short' devolve
// "ago. de 2026", e o resultado ainda varia entre versões do Node.
const MESES = ['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];
const [ano, mes] = String(p.mes_referencia).slice(0, 10).split('-');
const mesAno = `${MESES[Number(mes) - 1]}/${ano}`;

const L = ['💰 *Compensação registrada*', '', p.empresa];
if (p.tese) L.push(`${p.tese} — ${mesAno}`);
else L.push(mesAno);
L.push('');

for (const l of p.linhas || []) {
  L.push(`• ${l.tributo || '—'}: ${brl(l.valor)}`);
}

L.push('');
L.push(`Total: *${brl(p.total_compensado)}*`);

// Lista TODOS os percentuais distintos. Um mês pode ter INSS a 15% e PIS/COFINS
// a 20% — exibir só um repetiria o bug que o Focus reportou em 26/08.
const pcts = (p.percentuais || []).map((x) => {
  const n = Number(x);
  return `${n % 1 === 0 ? n.toFixed(0) : n.toFixed(1)}%`;
});
const rotulo = pcts.length === 0 ? ''
  : pcts.length === 1 ? ` (${pcts[0]})`
  : ` (${pcts.slice(0, -1).join(', ')} e ${pcts[pcts.length - 1]})`;

if (Number(p.total_honorarios) > 0) {
  L.push(`Honorários: ${brl(p.total_honorarios)}${rotulo}`);
}

return [{ json: { mensagem: L.join('\n') } }];
